create table if not exists public.notification_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,auction_ending boolean not null default true,outbid boolean not null default true,won boolean not null default true,order_updates boolean not null default true,push_enabled boolean not null default false,email_enabled boolean not null default true,updated_at timestamptz not null default now());alter table public.notification_preferences enable row level security;create policy "prefs own read" on public.notification_preferences for select using(auth.uid()=user_id);create policy "prefs own update" on public.notification_preferences for update using(auth.uid()=user_id) with check(auth.uid()=user_id);